package com.oracle.banking.twofa.config;
import org.springframework.stereotype.Component;
import com.oracle.banking.shared.constants.SecurityConstants; import io.jsonwebtoken.*; import io.jsonwebtoken.io.Decoders; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.SecretKey; import java.io.IOException; import java.util.*;
@Configuration public class SecurityConfiguration {@Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/swagger-ui/**","/v3/api-docs/**","/actuator/health","/internal/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}@Component static class JwtFilter extends OncePerRequestFilter{private final SecretKey key;JwtFilter(@Value("${security.jwt.secret}")String s){key=Keys.hmacShaKeyFor(Decoders.BASE64.decode(s));}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith(SecurityConstants.BEARER_PREFIX)&&SecurityContextHolder.getContext().getAuthentication()==null)try{Claims x=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload();@SuppressWarnings("unchecked") Collection<String> roles=x.get("roles",List.class);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(x.getSubject(),null,roles.stream().map(v->new SimpleGrantedAuthority("ROLE_"+v)).toList()));}catch(Exception e){SecurityContextHolder.clearContext();}c.doFilter(r,p);}}}
